insert into academy_paths (code, title, blurb, sort)
insert into academy_sections (slug, title, blurb, guide_refs) values ('r48-cs-guide-cases', 'Customer service: answers from the guide', 'Real messages from renters and what the guide says to do: where to click and what to say.', array['va/customer-service', 'va/texts-and-calls', 'va/shared-tools']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-cs-guide-cases'), 1, 'Ask the guide first', '[{"caption":"The guide answers it","say":"Most questions you would ask a colleague are answered in the guide, step by step, with the buttons named. Open the staff guide from the Guide link at the top of every page before you ask anyone.","visual":{"kind":"title","heading":"Ask the guide first","text":"Then ask a person"}},{"caption":"Help on every page","say":"The Assistant panel names the guide chapter of the page you are on, with a link. If you work on a page without getting anywhere, a small box offers the same chapter beside the page; everything you typed stays.","visual":{"kind":"list","heading":"Where the guide is","items":["Guide, at the top of every page","The Assistant: the chapter of this page","The Stuck box: the same chapter, beside the page"]}},{"caption":"Still stuck","say":"Read the chapter, try it, and only then ask in the team group, saying which chapter you read. That way the answer can be added to the guide for everyone.","visual":{"kind":"rule","heading":"Say what you read","text":"Name the chapter when you ask.","tone":"ok"}},{"caption":"Where to find it","say":"This is the chapter for your work.","visual":{"kind":"shot","heading":"Your guide","guide":"va/customer-service"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-cs-guide-cases'), 2, 'A request is waiting', '[{"caption":"The queue","say":"A request for a Corolla next weekend has waited 3 minutes. Open Requests and offers: the most urgent is at the top, with how long the renter has waited.","visual":{"kind":"shot","heading":"Requests and offers","guide":"va/customer-service","img":"va-cs-03-requests-desktop-b3c66d25.jpg","text":"The wait, the car, the renter with Call and Text, one button"}},{"caption":"Opening holds it","say":"Opening it holds it for you for 20 minutes, renewed while you work. On the Review tab check the car is free, the renter and the places.","visual":{"kind":"shot","heading":"The Review tab","guide":"va/customer-service","img":"va-cs-04-booking-review-desktop-52c68a73.jpg"}},{"caption":"Reply in 5 minutes","say":"Send the offer, or ask the renter what you need, within 5 minutes. That is the first reply measure on your scorecard.","visual":{"kind":"chat","lines":[{"who":"renter","text":"Is the Corolla free Saturday to Monday?"},{"who":"you","text":"It is. I just sent you the offer: open Trips, then Review offer. It stays open 24 hours."}]}},{"caption":"The car is taken","say":"Cannot do it? Decline with the reason and an alternative: other dates or a similar free car.","visual":{"kind":"chat","lines":[{"who":"you","text":"The Corolla is booked those days. The Civic is free for your dates at the same price. Want me to send that offer?"}]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-cs-guide-cases'), 3, 'Is my card good for coverage?', '[{"caption":"The question","say":"A renter texts that they will use their credit card for coverage. Never tell a renter they are covered: only the card issuer decides.","visual":{"kind":"chat","lines":[{"who":"renter","text":"My Visa covers rentals, right? So I don''t need anything else?"}]}},{"caption":"What you do","say":"Send the card coverage page, ask which car they want, and ask them to call the number on the back of their card about this car and these dates.","visual":{"kind":"steps","heading":"Card coverage","items":["Send carmacars.ca/credit-card-rental-coverage","Give the car''s year and trim","They call their card issuer","They pick their card on the booking"]}},{"caption":"What you say","say":"If the card does not cover the car, offer the two other options.","visual":{"kind":"chat","lines":[{"who":"you","text":"Your card issuer decides that, so please call the number on the back of your card about this car. If it does not cover it, you can use OPCF 27 on your own policy or our Protection Plan."}]}},{"caption":"Two pages for OPCF 27","say":"OPCF 27 needs two pages: the pink slip and the OPCF 27 endorsement page. Approve is refused until both are in.","visual":{"kind":"rule","heading":"OPCF 27","text":"Pink slip plus the endorsement page. Both, or no approval.","tone":"warn"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-cs-guide-cases'), 4, 'Running late', '[{"caption":"The text","say":"A renter texts that they will be an hour late returning. Point them to Extend first: it is approved at once when the car is free, and paying it stops the late notices.","visual":{"kind":"chat","lines":[{"who":"renter","text":"Stuck in traffic, I''ll be an hour late."},{"who":"you","text":"Thanks for telling us. Open your booking and press Extend, then 1 hour: it shows the price and stops the late notices once paid."}]}},{"caption":"Call first","say":"Calls come before texts. If they do not answer, a text is the follow-up, and every call goes in with Log a call.","visual":{"kind":"list","heading":"The late return panel","items":["Log a call","Send T13","Send T14 (final notice)","Request disable","Open an incident"]}},{"caption":"No charge by itself","say":"A late return is never charged by itself. Someone chooses the charge on the booking: as an extension, extra days, the late fee, a custom amount, or waive it with the reason.","visual":{"kind":"rule","heading":"A late return is a choice","text":"Nothing is charged until someone chooses.","tone":"ok"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-cs-guide-cases'), 1, 'A renter asks you something you are not sure about. What do you do first?', '["Ask an Admin in the group","Open the guide chapter for that page","Guess and correct it later","Tell the renter to email us"]'::jsonb, 1, 'Ask the guide first: the chapter for the page names the buttons and the steps.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-cs-guide-cases'), 2, 'Where does the Assistant panel point you before you ask?', '["To the guide chapter of the page you are on","To the renter''s profile","To the Admin''s phone","Nowhere"]'::jsonb, 0, 'The Assistant names the matching guide chapter, with a link.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-cs-guide-cases'), 3, 'How fast should you reply to a request in opening hours?', '["Within 5 minutes","Within 2 hours","By the end of the day","Within 24 hours"]'::jsonb, 0, 'Within 5 minutes: send the offer or ask the renter.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-cs-guide-cases'), 4, 'A renter asks if their credit card covers the rental. What do you say?', '["Yes, all cards do","Their card issuer decides: call the number on the back of the card about this car","No card ever covers rentals","Only if it is a Visa"]'::jsonb, 1, 'Never tell a renter they are covered. The issuer decides.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-cs-guide-cases'), 5, 'Which two pages does OPCF 27 need before you can approve it?', '["The licence front and back","The pink slip and the OPCF 27 endorsement page","A bank statement and a selfie","The ownership and the registration"]'::jsonb, 1, 'Approve is refused until both the pink slip and the endorsement page are in.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-cs-guide-cases'), 6, 'A renter will be an hour late. What do you point them to first?', '["Open an incident","Extend on their booking","Request disable","Nothing, the fee is charged by itself"]'::jsonb, 1, 'Extend first: approved at once when the car is free, and paying it stops the late notices.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-cs-guide-cases'), 7, 'The car asked for is booked. How do you decline?', '["Decline with no reason","Decline with the reason and an alternative","Leave it to expire","Cancel the other renter"]'::jsonb, 1, 'Give the reason and another car or other dates.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_path_sections (path_code, section_id, sort) select 'cs', (select id from academy_sections where slug = 'r48-cs-guide-cases'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'cs' on conflict (path_code, section_id) do nothing;
insert into academy_sections (slug, title, blurb, guide_refs) values ('r48-sales-guide-cases', 'Sales: answers from the guide', 'Leads, offers and getting a renter ready, as the Sales guide says: worked examples.', array['va/sales', 'va/customer-service']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-sales-guide-cases'), 1, 'Ask the guide first', '[{"caption":"The guide answers it","say":"Most questions you would ask a colleague are answered in the guide, step by step, with the buttons named. Open the staff guide from the Guide link at the top of every page before you ask anyone.","visual":{"kind":"title","heading":"Ask the guide first","text":"Then ask a person"}},{"caption":"Help on every page","say":"The Assistant panel names the guide chapter of the page you are on, with a link. If you work on a page without getting anywhere, a small box offers the same chapter beside the page; everything you typed stays.","visual":{"kind":"list","heading":"Where the guide is","items":["Guide, at the top of every page","The Assistant: the chapter of this page","The Stuck box: the same chapter, beside the page"]}},{"caption":"Still stuck","say":"Read the chapter, try it, and only then ask in the team group, saying which chapter you read. That way the answer can be added to the guide for everyone.","visual":{"kind":"rule","heading":"Say what you read","text":"Name the chapter when you ask.","tone":"ok"}},{"caption":"Where to find it","say":"This is the chapter for your work.","visual":{"kind":"shot","heading":"Your guide","guide":"va/sales"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-sales-guide-cases'), 2, 'A caller wants a car now', '[{"caption":"The call","say":"A caller wants an SUV for Friday and has agreed the price on the phone. Open Send an offer: no request is needed.","visual":{"kind":"chat","lines":[{"who":"caller","text":"I''ll take the RAV4 for Friday to Sunday at that price."},{"who":"you","text":"Great. I am sending you one link now to sign and pay."}]}},{"caption":"Book it now","say":"They already agreed, so tick Book it now (no renter approval). An Admin approves in one tap, the car is held and the renter gets one link to sign and pay.","visual":{"kind":"steps","heading":"Send an offer","items":["Find or add the customer","The car, dates and places","The price from the rate sheet","Tick Book it now","Send the offer"]}},{"caption":"Prices stay inside the limits","say":"A typed price needs its reason, and stays between the owner''s lowest and highest daily rate; only an Admin allows one outside them.","visual":{"kind":"rule","heading":"Price limits","text":"Inside the owner''s minimum and maximum.","tone":"warn"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-sales-guide-cases'), 3, 'Get the renter ready', '[{"caption":"Ready for the rental","say":"Your work does not stop at the offer. The booking shows Ready for the rental: one line for each thing the pickup needs, green when done.","visual":{"kind":"list","heading":"Ready for the rental","items":["Offer accepted","Paid","Licence and selfie","Coverage","Deposit","Drivers and agreement"]}},{"caption":"The licence","say":"Licences to check on your To do: look at each image and each Flag line, reject a wrong one with the reason the renter reads, then Approve all.","visual":{"kind":"chat","lines":[{"who":"you","text":"Your licence photo is cut off at the corner. Please take it again on a dark surface with all four corners showing."}]}},{"caption":"A driver still to sign","say":"An additional driver has not signed: send them their own signing link from the booking. Links last 72 hours and a new one ends the old one.","visual":{"kind":"rule","heading":"Signing links","text":"Always send the newest link.","tone":"ok"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-sales-guide-cases'), 4, 'The offer expired', '[{"caption":"Win them back","say":"An offer expired 7 days ago becomes a renter lead with the To do Expired offer: win the renter back. Call first, then text.","visual":{"kind":"chat","lines":[{"who":"you","text":"Hi, your offer for the Civic ended. It is still free for your dates: want me to reopen it?"},{"who":"renter","text":"Yes please."}]}},{"caption":"Reopen offer","say":"Reopen offer on the expired booking sends it again in one click, open 24 hours. A pickup time that has passed asks for new dates first.","visual":{"kind":"steps","heading":"Reopen","items":["Open the expired booking","Reopen offer","New dates if the pickup passed"]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-sales-guide-cases'), 1, 'A caller agreed the price on the phone. What do you tick when you send the offer?', '["Nothing","Book it now (no renter approval)","Non-refundable","Save without telling the renter"]'::jsonb, 1, 'Book it now: an Admin approves in one tap and the renter gets one link to sign and pay.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-sales-guide-cases'), 2, 'Who allows a price outside the owner''s daily minimum and maximum?', '["You, with a reason","Only an Admin","The renter","Customer service"]'::jsonb, 1, 'Only an Admin allows one booking outside the limits.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-sales-guide-cases'), 3, 'Where do you see everything the pickup still needs?', '["Ready for the rental on the booking","The renter''s email","My sales only","Nowhere"]'::jsonb, 0, 'Ready for the rental lists each thing, green when done.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-sales-guide-cases'), 4, 'A licence photo is cut off. What do you do?', '["Approve it anyway","Reject this one with the reason the renter reads","Delete the booking","Ask the renter to email it"]'::jsonb, 1, 'Reject with a reason: the renter is told and sends a new one.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-sales-guide-cases'), 5, 'How long does an additional driver''s signing link last?', '["1 hour","72 hours","30 days","Forever"]'::jsonb, 1, 'Signing links expire after 72 hours; a new one ends the older one.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-sales-guide-cases'), 6, 'How long is an offer open after Reopen offer, unless you set the hours?', '["24 hours","1 hour","7 days","Until pickup"]'::jsonb, 0, 'Reopen offer sends it again, open 24 hours.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-sales-guide-cases'), 7, 'Before asking a colleague how a Sales screen works, what do you open?', '["The Sales chapter of the guide","The renter''s chat","My call minutes","Nothing"]'::jsonb, 0, 'Ask the guide first.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_path_sections (path_code, section_id, sort) select 'sales_in_person', (select id from academy_sections where slug = 'r48-sales-guide-cases'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'sales_in_person' on conflict (path_code, section_id) do nothing;
insert into academy_path_sections (path_code, section_id, sort) select 'sales_remote', (select id from academy_sections where slug = 'r48-sales-guide-cases'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'sales_remote' on conflict (path_code, section_id) do nothing;
insert into academy_sections (slug, title, blurb, guide_refs) values ('r48-fleet-guide-cases', 'Fleet: answers from the guide', 'Field jobs, shifts, late cars and the renter who says the car is back: worked examples from the Fleet guide.', array['va/fleet']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-fleet-guide-cases'), 1, 'Ask the guide first', '[{"caption":"The guide answers it","say":"Most questions you would ask a colleague are answered in the guide, step by step, with the buttons named. Open the staff guide from the Guide link at the top of every page before you ask anyone.","visual":{"kind":"title","heading":"Ask the guide first","text":"Then ask a person"}},{"caption":"Help on every page","say":"The Assistant panel names the guide chapter of the page you are on, with a link. If you work on a page without getting anywhere, a small box offers the same chapter beside the page; everything you typed stays.","visual":{"kind":"list","heading":"Where the guide is","items":["Guide, at the top of every page","The Assistant: the chapter of this page","The Stuck box: the same chapter, beside the page"]}},{"caption":"Still stuck","say":"Read the chapter, try it, and only then ask in the team group, saying which chapter you read. That way the answer can be added to the guide for everyone.","visual":{"kind":"rule","heading":"Say what you read","text":"Name the chapter when you ask.","tone":"ok"}},{"caption":"Where to find it","say":"This is the chapter for your work.","visual":{"kind":"shot","heading":"Your guide","guide":"va/fleet"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-fleet-guide-cases'), 2, 'A pickup nobody covers', '[{"caption":"The alert","say":"A shift with jobs and nobody on it is marked on Field jobs, and within 24 hours of its start you get an alert and a To do.","visual":{"kind":"shot","heading":"Field jobs","guide":"va/fleet","img":"va-fleet-02-field-jobs-desktop-8e721230.jpg","text":"Jobs, next three days, and Shifts, next seven days"}},{"caption":"Cover it","say":"Add a person to the shift, or Assign the job to a field person on a shift that day. A person who has not passed the academy cannot take shifts or jobs.","visual":{"kind":"steps","heading":"Cover the shift","items":["Open Field jobs","Shifts, next seven days","Add a person, or Assign the job"]}},{"caption":"Never move the renter","say":"Work on a day with no shifts moves to the day before, but the renter''s times never change.","visual":{"kind":"rule","heading":"The renter''s time stays","text":"Cover the job, or ask to move the booking.","tone":"warn"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-fleet-guide-cases'), 3, 'The renter says the car is back', '[{"caption":"The To do","say":"An urgent To do: The renter says the car is back. They pressed I''ve returned the car on an overdue booking, and their late notices are paused.","visual":{"kind":"chat","lines":[{"who":"renter","text":"I left the car at the lot an hour ago, why am I still getting late messages?"},{"who":"you","text":"Thanks, I am checking it now. The late messages are paused while I do."}]}},{"caption":"Check, then decide","say":"Check the place, the tracker and the renter''s photos. Confirm (fix the odometer, fuel or time first) or Deny with the reason, and the notices start again.","visual":{"kind":"steps","heading":"Confirm or deny","items":["Open the booking","Check place, tracker, photos","Confirm, or Deny with the reason"]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-fleet-guide-cases'), 4, 'A car still driving after its return time', '[{"caption":"The map alert","say":"The fleet map alerts you that a car is still driving after its return time. Call the renter first.","visual":{"kind":"chat","lines":[{"who":"you","text":"Hi, your return time was 6 pm and the car is still on the road. You can extend from your booking, or tell me when you will be back."}]}},{"caption":"Then the late return","say":"Send the late notice and offer a paid extension, as for any late return. The late charge is chosen later; nothing is charged by itself.","visual":{"kind":"rule","heading":"Late return: choose the charge","text":"Fleet has this To do until someone chooses.","tone":"ok"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-fleet-guide-cases'), 1, 'A shift has jobs and nobody on it. When are you alerted?', '["Never","Within 24 hours of its start, once","Only after the job is missed","Every hour"]'::jsonb, 1, 'An alert and a To do within 24 hours of the start, once.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-fleet-guide-cases'), 2, 'Who can be given a field job by itself?', '["Anyone","A field person who passed the academy and holds a shift that day","Only Admins","Only Sales"]'::jsonb, 1, 'Passed the academy and on a shift that day.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-fleet-guide-cases'), 3, 'A renter pressed I''ve returned the car. What happens to their late notices?', '["They continue","They are paused while you check","They double","They go to the owner"]'::jsonb, 1, 'The notices pause while Fleet checks.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-fleet-guide-cases'), 4, 'You find the car is not where the renter said. What do you press?', '["Confirm","Deny with the reason","Nothing","Delete the booking"]'::jsonb, 1, 'Deny with the reason: the renter is told and the notices start again.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-fleet-guide-cases'), 5, 'A car is still driving after its return time. What do you do first?', '["Disable the car","Call the renter","Charge a late fee","Email the owner"]'::jsonb, 1, 'Call first, then the late notice and a paid extension.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-fleet-guide-cases'), 6, 'Work lands on a day with no shifts. What happens to the renter''s pickup time?', '["It moves to the day before","It never changes","It is cancelled","It moves to the next shift"]'::jsonb, 1, 'The job moves; the renter''s times never change.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_path_sections (path_code, section_id, sort) select 'fleet', (select id from academy_sections where slug = 'r48-fleet-guide-cases'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'fleet' on conflict (path_code, section_id) do nothing;
insert into academy_sections (slug, title, blurb, guide_refs) values ('r48-finance-guide-cases', 'Finance: answers from the guide', 'Deposits, payments taken another way and refunds, as the Finance guide says: worked examples.', array['va/finance']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-finance-guide-cases'), 1, 'Ask the guide first', '[{"caption":"The guide answers it","say":"Most questions you would ask a colleague are answered in the guide, step by step, with the buttons named. Open the staff guide from the Guide link at the top of every page before you ask anyone.","visual":{"kind":"title","heading":"Ask the guide first","text":"Then ask a person"}},{"caption":"Help on every page","say":"The Assistant panel names the guide chapter of the page you are on, with a link. If you work on a page without getting anywhere, a small box offers the same chapter beside the page; everything you typed stays.","visual":{"kind":"list","heading":"Where the guide is","items":["Guide, at the top of every page","The Assistant: the chapter of this page","The Stuck box: the same chapter, beside the page"]}},{"caption":"Still stuck","say":"Read the chapter, try it, and only then ask in the team group, saying which chapter you read. That way the answer can be added to the guide for everyone.","visual":{"kind":"rule","heading":"Say what you read","text":"Name the chapter when you ask.","tone":"ok"}},{"caption":"Where to find it","say":"This is the chapter for your work.","visual":{"kind":"shot","heading":"Your guide","guide":"va/finance"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-finance-guide-cases'), 2, 'Where is my deposit?', '[{"caption":"The question","say":"A renter returned the car yesterday and asks where their deposit is. A deposit is never given back by itself: Finance or an Admin settles it after the return.","visual":{"kind":"chat","lines":[{"who":"renter","text":"I returned the car yesterday. When do I get my deposit back?"}]}},{"caption":"The toll window","say":"Tolls and tickets can take up to 7 days to come in. Inside that window the rest of the deposit is held back, unless you tick Release now anyway.","visual":{"kind":"money","heading":"Settle the deposit","rows":[["Deposit","$500.00"],["Charges from the statement","$40.00"],["Held for tolls (7 days)","$460.00"]],"total":["Released now","$0.00"]}},{"caption":"What you say","say":"Tell them when it comes back and why.","visual":{"kind":"chat","lines":[{"who":"you","text":"Your deposit is held for up to 7 days after the return, in case a toll or ticket comes in. After that the rest is released to your card; your bank can take a few days to show it."}]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-finance-guide-cases'), 3, 'Paid by e-Transfer', '[{"caption":"The text","say":"A renter says they paid the balance by e-Transfer. Record it on the booking''s Money tab: Collect, then Cash, e-Transfer or another way (record it).","visual":{"kind":"chat","lines":[{"who":"renter","text":"I sent the $120 by e-Transfer just now."},{"who":"you","text":"Thank you. I have recorded it with your reference: your booking now shows it paid."}]}},{"caption":"The details","say":"Choose Paid by, the date received and the reference, add the proof if you have it, then Record payment. Above your single limit it needs an Admin.","visual":{"kind":"steps","heading":"Record it","items":["Money tab","Collect, another way","Paid by, date, reference","Record payment"]}},{"caption":"A mistake","say":"Recorded something wrong? You cannot void a payment: ask an Admin to void it.","visual":{"kind":"rule","heading":"No voids","text":"An Admin voids a wrong payment.","tone":"warn"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-finance-guide-cases'), 4, 'A hold about to lapse', '[{"caption":"The To do","say":"The deposit hold expires soon. A job re-authorizes it about 24 hours before; when it cannot, you get the alert. Re-authorize the hold, or Keep part for only what is owed.","visual":{"kind":"shot","heading":"Money","guide":"va/finance","img":"va-finance-02-money-desktop-486a8fbc.jpg","text":"To handle: failed payments, deposits, refunds"}},{"caption":"Countdowns","say":"Money, Countdowns shows the time left on each hold and deposit due back. Red is within 24 hours or late, amber within 48.","visual":{"kind":"list","heading":"Countdowns","items":["Hold expires","Deposit due back","Next plan payment"]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-finance-guide-cases'), 1, 'Is a deposit ever given back by itself?', '["Yes, at the return","No: Finance or an Admin settles it after the return","Yes, after 24 hours","Only on weekends"]'::jsonb, 1, 'Never by itself: it is settled after the return.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-finance-guide-cases'), 2, 'How long can tolls and tickets take to come in?', '["1 hour","Up to 7 days","90 days","They never come"]'::jsonb, 1, 'Up to 7 days: the rest of the deposit is held back inside that window.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-finance-guide-cases'), 3, 'A renter paid by e-Transfer. Where do you record it?', '["The renter''s profile","The booking''s Money tab, Collect, another way","An email to an Admin","Nowhere"]'::jsonb, 1, 'Money tab: Collect, then Cash, e-Transfer or another way (record it).') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-finance-guide-cases'), 4, 'You recorded a payment wrong. What do you do?', '["Void it yourself","Ask an Admin to void it","Record a second one","Ignore it"]'::jsonb, 1, 'Finance cannot void a payment: an Admin does.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-finance-guide-cases'), 5, 'When does the automatic job try to re-authorize a deposit hold?', '["About 24 hours before it expires","After it expires","At pickup only","Never"]'::jsonb, 0, 'About 24 hours before it expires; you are alerted if it cannot.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-finance-guide-cases'), 6, 'On Countdowns, what does red mean?', '["Within 24 hours or late","Paid","More than a week left","Refunded"]'::jsonb, 0, 'Red is within 24 hours or late, amber within 48.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_path_sections (path_code, section_id, sort) select 'finance', (select id from academy_sections where slug = 'r48-finance-guide-cases'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'finance' on conflict (path_code, section_id) do nothing;
insert into academy_sections (slug, title, blurb, guide_refs) values ('r48-field-guide-cases', 'Field work: answers from the guide', 'At the car with the renter: the ready check, the deposit, cash and add-ons, as the field guide says.', array['field/a-handover', 'field/my-jobs', 'field/a-return']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-field-guide-cases'), 1, 'Ask the guide first', '[{"caption":"The guide answers it","say":"Most questions you would ask a colleague are answered in the guide, step by step, with the buttons named. Open the field guide from the Guide link at the top of every page before you ask anyone.","visual":{"kind":"title","heading":"Ask the guide first","text":"Then ask a person"}},{"caption":"Help on every page","say":"The Assistant panel names the guide chapter of the page you are on, with a link. If you work on a page without getting anywhere, a small box offers the same chapter beside the page; everything you typed stays.","visual":{"kind":"list","heading":"Where the guide is","items":["Guide, at the top of every page","The Assistant: the chapter of this page","The Stuck box: the same chapter, beside the page"]}},{"caption":"Still stuck","say":"Read the chapter, try it, and only then ask in the team group, saying which chapter you read. That way the answer can be added to the guide for everyone.","visual":{"kind":"rule","heading":"Say what you read","text":"Name the chapter when you ask.","tone":"ok"}},{"caption":"Where to find it","say":"This is the chapter for your work.","visual":{"kind":"shot","heading":"Your guide","guide":"field/a-handover"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-field-guide-cases'), 2, 'The ready check is red', '[{"caption":"What you see","say":"You arrive for a pickup and the ready check has a red line. Each red line shows what you can do right under it.","visual":{"kind":"shot","heading":"The ready check","guide":"field/a-handover","img":"field-21-handover-01-ready-phone-ecb54c56.jpg","text":"Six checks: signed, identity, coverage, drivers, calendar, deposit"}},{"caption":"Fix it on your phone","say":"Not signed: Sign now on this device. Deposit not taken: Card hold, hand this phone to the renter. Never type a card number yourself.","visual":{"kind":"chat","lines":[{"who":"renter","text":"Can I just read you my card number?"},{"who":"you","text":"For your safety I never type card numbers. Please type it here in the secure form on my phone."}]}},{"caption":"Only the office","say":"Coverage or the calendar not ready? Only the office fixes those: call CarmaCars. Still not ready? Stop: do not release the car.","visual":{"kind":"rule","heading":"Never hand over the keys","text":"If the ready check fails, the face does not match, or there is no original licence.","tone":"warn"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-field-guide-cases'), 3, 'No original licence', '[{"caption":"The renter","say":"The renter shows a photo of their licence on their phone. A photo of a licence is not enough.","visual":{"kind":"chat","lines":[{"who":"renter","text":"I left my licence at home but here is a picture of it."},{"who":"you","text":"I am sorry, I need the original licence to hand over the car. I will call the office so we can find the best way."}]}},{"caption":"Stop and call","say":"Do not fix it: press Stop and call us. The same for an expired licence, a face that does not match, or a renter who will not sign.","visual":{"kind":"steps","heading":"Stop","items":["Do not hand over the keys","Press Stop","Call the office"]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-field-guide-cases'), 4, 'Cash and add-ons', '[{"caption":"Paid in cash","say":"Open Paid in cash, count the amount in front of the renter and press I received. Keep it apart from your own money and hand it to CarmaCars within 1 business day.","visual":{"kind":"money","heading":"Cash at the car","rows":[["Counted with the renter","$300.00"],["Handed to CarmaCars","within 1 business day"]]}},{"caption":"The child seat","say":"The pickup cannot be finished until every add-on is ticked as in the car. Missing? Write it under Add a note for Fleet and call the office before the handover.","visual":{"kind":"rule","heading":"Every add-on ticked","text":"Or an Admin overrides on the job.","tone":"warn"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-field-guide-cases'), 1, 'The renter wants to read you their card number for the deposit. What do you do?', '["Type it in for them","Hand them the phone: they type it in the secure form","Write it down","Skip the deposit"]'::jsonb, 1, 'Never type a card number: Card hold, hand this phone to the renter.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-field-guide-cases'), 2, 'Coverage is not ready on the ready check. Who fixes it?', '["You, on your phone","Only the office: call CarmaCars","The renter at the car","Nobody, go ahead"]'::jsonb, 1, 'Coverage and the calendar are fixed by the office only.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-field-guide-cases'), 3, 'The renter has only a photo of their licence. What do you do?', '["Accept the photo","Stop and call the office","Ask for a credit card instead","Hand over the keys"]'::jsonb, 1, 'A photo is not enough: Stop and call us.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-field-guide-cases'), 4, 'You received cash at the car. When does it go to CarmaCars?', '["Within 1 business day","At the end of the month","Never, keep it","After the return"]'::jsonb, 0, 'Kept apart and handed over within 1 business day.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-field-guide-cases'), 5, 'A child seat on the booking is not in the car. Can you finish the pickup?', '["Yes","No: every add-on must be ticked, or an Admin overrides","Yes, if the renter agrees","Only on weekends"]'::jsonb, 1, 'Every add-on ticked as in the car, or an Admin overrides.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-field-guide-cases'), 6, 'Before asking the office how a screen works, what do you open?', '["The field guide chapter","The renter''s email","Your pay stub","Nothing"]'::jsonb, 0, 'Ask the guide first.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_path_sections (path_code, section_id, sort) select 'field', (select id from academy_sections where slug = 'r48-field-guide-cases'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'field' on conflict (path_code, section_id) do nothing;
insert into academy_sections (slug, title, blurb, guide_refs) values ('r48-admin-guide-cases', 'Admin: answers from the guide', 'What staff ask an Admin most, and the guide chapter that answers it: worked examples.', array['admin/requests-offers-and-bookings', 'admin/people-and-access']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-admin-guide-cases'), 1, 'Ask the guide first', '[{"caption":"The guide answers it","say":"Most questions you would ask a colleague are answered in the guide, step by step, with the buttons named. Open the Admin guide from the Guide link at the top of every page before you ask anyone.","visual":{"kind":"title","heading":"Ask the guide first","text":"Then ask a person"}},{"caption":"Help on every page","say":"The Assistant panel names the guide chapter of the page you are on, with a link. If you work on a page without getting anywhere, a small box offers the same chapter beside the page; everything you typed stays.","visual":{"kind":"list","heading":"Where the guide is","items":["Guide, at the top of every page","The Assistant: the chapter of this page","The Stuck box: the same chapter, beside the page"]}},{"caption":"Still stuck","say":"Read the chapter, try it, and only then ask in the team group, saying which chapter you read. That way the answer can be added to the guide for everyone.","visual":{"kind":"rule","heading":"Say what you read","text":"Name the chapter when you ask.","tone":"ok"}},{"caption":"Where to find it","say":"This is the chapter for your work.","visual":{"kind":"shot","heading":"Your guide","guide":"admin/requests-offers-and-bookings"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-admin-guide-cases'), 2, 'Send them to the chapter', '[{"caption":"A staff question","say":"A new customer service person asks you how to answer a request. The answer is in their guide: send the chapter, not a long message.","visual":{"kind":"chat","lines":[{"who":"staff","text":"How do I answer a request with an offer?"},{"who":"you","text":"It is in your guide, Customer service, Answer a request. Read it, try it, and tell me which step is not clear."}]}},{"caption":"The same screens","say":"Your own chapter is Requests, offers and bookings: the same queue, with Take over when someone holds a request.","visual":{"kind":"shot","heading":"Requests and offers","guide":"admin/requests-offers-and-bookings","img":"admin-02-requests-desktop-6521282d.jpg"}},{"caption":"Fix the guide","say":"If the guide did not answer it, fix the guide in Settings, Guides, so the next person finds it.","visual":{"kind":"rule","heading":"One answer for everyone","text":"A missing answer goes into the guide.","tone":"ok"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-admin-guide-cases'), 3, 'A pickup that must go ahead', '[{"caption":"The request","say":"Field staff ask you to override a pickup the ready check stops. You get an alert and approve in one tap; the pickup is recorded with the time they entered.","visual":{"kind":"chat","lines":[{"who":"staff","text":"The renter is here, the tracker is not reporting and the car must go."},{"who":"you","text":"Send the override from the job with the reason, I will approve it now."}]}},{"caption":"Deposit still owed","say":"A car out with the deposit owed shows Deposit pending. The saved card is tried each morning; after 48 hours unpaid you get the To do Deposit still owed, opening the Money tab.","visual":{"kind":"rule","heading":"48 hours","text":"Then the To do comes to you.","tone":"warn"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-admin-guide-cases'), 4, 'New staff and the academy', '[{"caption":"The order","say":"Every staff member opens their portal in order: the academy, then the staff agreement, then the WhatsApp groups and the approval.","visual":{"kind":"steps","heading":"Onboarding","items":["Pass the academy","Sign the staff agreement","Join the WhatsApp groups","Approval"]}},{"caption":"The renter''s side","say":"Release 48 adds the path The renter''s side for every staff role. New hires take it from the start; staff already working have 7 days before it holds them.","visual":{"kind":"rule","heading":"7 days","text":"Then their portal waits until it is passed.","tone":"ok"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-admin-guide-cases'), 1, 'A staff member asks how a screen works and the guide answers it. What do you send?', '["A long message","The guide chapter","Nothing","A video call invite"]'::jsonb, 1, 'Send the chapter: ask the guide first.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-admin-guide-cases'), 2, 'The guide did not answer a staff question. What do you do?', '["Nothing","Fix the guide in Settings, Guides","Answer only that person","Delete the chapter"]'::jsonb, 1, 'Put the answer into the guide for everyone.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-admin-guide-cases'), 3, 'After how long unpaid does Deposit still owed come to you as a To do?', '["48 hours","1 hour","7 days","Never"]'::jsonb, 0, 'After 48 hours still unpaid.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-admin-guide-cases'), 4, 'In what order does a new staff member open their portal?', '["Agreement, academy, approval","Academy, agreement, WhatsApp groups, approval","Approval first","All at once"]'::jsonb, 1, 'The academy first, then the agreement, the groups and the approval.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-admin-guide-cases'), 5, 'Staff already working get how long before The renter''s side holds them?', '["No time","7 days","30 days","It never holds them"]'::jsonb, 1, 'Seven days, then their portal waits until it is passed.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-admin-guide-cases'), 6, 'Who approves an override of a pickup the ready check stops?', '["An Admin, in one tap","The renter","Any field person","Nobody"]'::jsonb, 0, 'An Admin approves in one tap.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_path_sections (path_code, section_id, sort) select 'admin', (select id from academy_sections where slug = 'r48-admin-guide-cases'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'admin' on conflict (path_code, section_id) do nothing;
insert into academy_sections (slug, title, blurb, guide_refs) values ('r48-renter-request', 'How a renter requests a car', 'Find a car, the five steps of a request and the licence upload, as the renter sees them.', array['renter/find-a-car-and-send-a-request', 'renter/start-here']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-renter-request'), 1, 'Find a car', '[{"caption":"No sign-in needed","say":"The renter starts on the site with Find a car. With dates added, the list shows the cars that are free and what the whole trip costs.","visual":{"kind":"shot","heading":"Find a car","guide":"renter/find-a-car-and-send-a-request","img":"public-02-cars-desktop-b6cd4fb8.jpg"}},{"caption":"The car page","say":"On a car they tap the pickup and return dates (hatched days are booked), the times, delivery and add-ons, then Request to book. Its car code, like CC-7F3A, is under the price.","visual":{"kind":"shot","heading":"The car page","guide":"renter/find-a-car-and-send-a-request","img":"public-03-car-page-desktop-73be4d63.jpg"}},{"caption":"Ask for the car code","say":"When a renter calls about a car, ask for the code under the price: you know the car at once.","visual":{"kind":"chat","lines":[{"who":"renter","text":"I am looking at a grey SUV on your site."},{"who":"you","text":"Under the price there is a car code, like CC and four letters. Can you read it to me?"}]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-renter-request'), 2, 'The five steps', '[{"caption":"The steps","say":"The request has five short steps, saved as they go: dates and delivery, the driver, the licence and coverage, add-ons, then check it and send.","visual":{"kind":"steps","heading":"The request","items":["Dates and delivery","The driver","Licence class and coverage","Add-ons","Check it and send"]}},{"caption":"Coverage is chosen here","say":"On step 3 the renter picks Option 1 (OPCF 27 on their own policy), Option 2 (their credit card) or Option 3 (the Protection Plan). They can change it until pickup.","visual":{"kind":"shot","heading":"Step 3","guide":"renter/find-a-car-and-send-a-request","img":"public-06-book-3-licence-desktop-22bb144e.jpg"}},{"caption":"Nothing is charged","say":"Send request charges nothing and needs no card. The request number, like CC-10021, is on the confirmation.","visual":{"kind":"shot","heading":"Request sent","guide":"renter/find-a-car-and-send-a-request","img":"public-08-book-5-sent-phone-14a99ccf.jpg"}},{"caption":"A request does not hold the car","say":"The car is booked only once they approve the offer. Tell renters this plainly.","visual":{"kind":"chat","lines":[{"who":"renter","text":"I sent the request, so the car is mine?"},{"who":"you","text":"Not yet: we send you an offer, usually within 2 hours. The car is booked once you approve it."}]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-renter-request'), 3, 'The licence and the main driver', '[{"caption":"Upload the licence","say":"Right after the request: the front, the back and a selfie holding it. They need the licence on file to accept the offer.","visual":{"kind":"list","heading":"The licence","items":["Front","Back","Selfie holding it","Valid after the return"]}},{"caption":"Ontario licence","say":"The main driver needs an Ontario licence. A driver from elsewhere stays on as an extra driver; the renter presses Add main driver.","visual":{"kind":"rule","heading":"The main driver","text":"Holds an Ontario licence. Others can drive as extra drivers.","tone":"warn"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-request'), 1, 'A renter sent a request. Is the car booked?', '["Yes, at once","No: it is booked once they approve the offer","Yes, after 2 hours","Only if they paid"]'::jsonb, 1, 'A request does not hold the car.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-request'), 2, 'Where is the car code a renter can read to you?', '["Under the price on the car page","On the licence","In the footer","Nowhere"]'::jsonb, 0, 'The car code, like CC-7F3A, is under the price.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-request'), 3, 'On which step of the request does the renter choose coverage?', '["Step 1","Step 3, with the licence class","After pickup","Step 5 only"]'::jsonb, 1, 'Step 3: licence class, coverage and booking type.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-request'), 4, 'Does sending a request charge the renter?', '["Yes, the full price","No: nothing is charged and no card is needed","Yes, the deposit","Yes, $1"]'::jsonb, 1, 'Nothing is charged at the request.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-request'), 5, 'The renter''s licence is from another province. What does the booking ask?', '["Nothing","A main driver with an Ontario licence","A second deposit","A new request"]'::jsonb, 1, 'The main driver holds an Ontario licence; they stay on as an extra driver.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_path_sections (path_code, section_id, sort) select 'renter_side', (select id from academy_sections where slug = 'r48-renter-request'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'renter_side' on conflict (path_code, section_id) do nothing;
insert into academy_sections (slug, title, blurb, guide_refs) values ('r48-renter-offer', 'How a renter reads and accepts an offer', 'Trips, Review offer, Approve and continue, Ask for a change, and an offer that expired.', array['renter/your-offer']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-renter-offer'), 1, 'Open the offer', '[{"caption":"Do this next","say":"The offer arrives by email and in Trips. Do this next, at the top, has one sentence, the time left and one red button: Review offer.","visual":{"kind":"shot","heading":"Trips","guide":"renter/your-offer","img":"renter-02-trips-offer-desktop-27603c14.jpg"}},{"caption":"The offer page","say":"The price, dates, place and your message. The black bar shows how long it stays open: 24 hours.","visual":{"kind":"shot","heading":"The offer","guide":"renter/your-offer","img":"renter-03-offer-desktop-cae88b00.jpg"}},{"caption":"Three choices","say":"Approve and continue, Ask for a change, or Decline offer. With no licence on file the button says Upload your licence to accept.","visual":{"kind":"list","heading":"On the offer","items":["Approve and continue","Ask for a change","Decline offer"]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-renter-offer'), 2, 'Help on the phone', '[{"caption":"Cannot accept","say":"A renter calls: the button says Upload your licence to accept. Their licence is not on file yet.","visual":{"kind":"chat","lines":[{"who":"renter","text":"I can''t approve, it asks for my licence."},{"who":"you","text":"That is right: upload the front, the back and a selfie from that button, then come back to the offer and press Approve and continue."}]}},{"caption":"It expired","say":"On the expired offer the renter presses Ask to reopen this offer. You get a To do at once; they can ask once every 6 hours.","visual":{"kind":"chat","lines":[{"who":"renter","text":"My offer expired last night."},{"who":"you","text":"Press Ask to reopen this offer on it. I see your request now and will reopen it for you."}]}},{"caption":"Approving books the car","say":"Approving books the car, before paying. The booking shows Booked, payment due until they sign and pay.","visual":{"kind":"rule","heading":"Booked, payment due","text":"Collect the payment before pickup.","tone":"ok"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-offer'), 1, 'How long does an offer stay open by default?', '["24 hours","1 hour","7 days","Until pickup"]'::jsonb, 0, 'An offer stays open for 24 hours.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-offer'), 2, 'The renter''s button says Upload your licence to accept. Why?', '["The offer expired","Their licence is not on file yet","The card was declined","The car is taken"]'::jsonb, 1, 'They need the licence on file to accept.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-offer'), 3, 'What does the renter press on an expired offer?', '["Decline offer","Ask to reopen this offer","Cancel booking","Send request"]'::jsonb, 1, 'Ask to reopen this offer: a To do comes to you at once.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-offer'), 4, 'How often can a renter ask to reopen an offer?', '["Once every 6 hours","Once a week","Without limit","Never"]'::jsonb, 0, 'Once every 6 hours.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-offer'), 5, 'What does the booking show after the renter approves but before paying?', '["Cancelled","Booked, payment due","Returned","On trip"]'::jsonb, 1, 'Approving books the car: Booked, payment due.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_path_sections (path_code, section_id, sort) select 'renter_side', (select id from academy_sections where slug = 'r48-renter-offer'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'renter_side' on conflict (path_code, section_id) do nothing;
insert into academy_sections (slug, title, blurb, guide_refs) values ('r48-renter-details-sign', 'Complete your details and sign', 'The Sign and pay page: the details for the agreement, the initials, the consents and one signature.', array['renter/sign-and-pay']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-renter-details-sign'), 1, 'Complete your details', '[{"caption":"What only they can give","say":"If the agreement is missing something only the renter can give (date of birth, home address, mobile, licence number or expiry, insurance or card details), the booking shows Complete your details at the top.","visual":{"kind":"shot","heading":"Your details","guide":"renter/sign-and-pay","img":"renter-04-sign-details-desktop-bd193670.jpg"}},{"caption":"Save once","say":"They fill it in once and press Save my details (Save details on Sign and pay). The agreement then shows them; we keep them for next time.","visual":{"kind":"chat","lines":[{"who":"renter","text":"It keeps asking for my address before I can sign."},{"who":"you","text":"Fill it in once under Complete your details and press Save my details. The agreement then shows it and you can sign."}]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-renter-details-sign'), 2, 'Sign', '[{"caption":"Read and initial","say":"They check the key values at the top, tap All four for the statements, initial each key term, tick the three consents and draw their signature.","visual":{"kind":"shot","heading":"Ready to sign","guide":"renter/sign-and-pay","img":"renter-06-sign-ready-desktop-1eee20a4.jpg"}},{"caption":"One signature, two agreements","say":"One signature signs both: ours and Blind Spot''s, since we rent under Blind Spot''s insurance. The page then goes straight to the card form.","visual":{"kind":"rule","heading":"Both agreements","text":"One signature signs both.","tone":"ok"}},{"caption":"Signed online only","say":"A paper copy is never accepted. At the desk or the car they can sign on our device with Sign now on this device.","visual":{"kind":"chat","lines":[{"who":"renter","text":"Can I just print it and sign?"},{"who":"you","text":"We only take the signature online. I can send you the link, or you can sign on my tablet right now."}]}},{"caption":"Another driver","say":"Some bookings need every driver to sign before paying. Each driver gets their own link; the renter can send a new one from the booking.","visual":{"kind":"steps","heading":"Another driver","items":["Sign and pay says who still signs","Each driver gets a link","The card form opens once they signed"]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-details-sign'), 1, 'The booking shows Complete your details. What is it asking for?', '["A new request","Something only the renter can give, like their home address","The deposit","A review"]'::jsonb, 1, 'Details only the renter can give for the agreement.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-details-sign'), 2, 'How many agreements does the renter''s one signature sign?', '["One","Both: ours and Blind Spot''s","None","Three"]'::jsonb, 1, 'One signature signs both agreements.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-details-sign'), 3, 'A renter wants to sign on paper. What do you say?', '["Fine, scan it","We take the signature online only: the link, or our device","Email it to us","No signature is needed"]'::jsonb, 1, 'A paper copy is never accepted.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-details-sign'), 4, 'What does the renter tap to tick the four statements?', '["All four","Sign","Save details","Pay"]'::jsonb, 0, 'All four ticks the four statements.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-details-sign'), 5, 'Another driver still has to sign. When does the card form open?', '["At once","As soon as they have signed","After pickup","Never"]'::jsonb, 1, 'The card form opens once every driver needed has signed.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_path_sections (path_code, section_id, sort) select 'renter_side', (select id from academy_sections where slug = 'r48-renter-details-sign'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'renter_side' on conflict (path_code, section_id) do nothing;
insert into academy_sections (slug, title, blurb, guide_refs) values ('r48-renter-pay-deposit', 'Paying, and the deposit hold', 'What the renter pays now, the deposit at pickup, debit cards, and a deposit still owed.', array['renter/sign-and-pay', 'renter/before-pickup', 'renter/during-your-trip']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-renter-pay-deposit'), 1, 'Pay to confirm', '[{"caption":"What you pay now","say":"The pay step shows What you pay now and the Pay button with the amount. The card is authorized now and charged once the booking is confirmed.","visual":{"kind":"shot","heading":"Pay","guide":"renter/sign-and-pay","img":"renter-07-pay-desktop-705896d6.jpg"}},{"caption":"The deposit is not today","say":"The refundable deposit is taken at pickup, about an hour before, on the card they paid with. It is a hold, not a charge.","visual":{"kind":"chat","lines":[{"who":"renter","text":"Why was I not charged the deposit?"},{"who":"you","text":"The deposit is a hold placed about an hour before pickup on the card you paid with. It is released after the return."}]}},{"caption":"Debit and prepaid cards","say":"On a debit or prepaid card the deposit may be charged instead of held, with a non-refundable card processing fee shown before they pay. The deposit comes back; the fee does not.","visual":{"kind":"rule","heading":"Debit deposit","text":"The fee is shown first and is not refunded.","tone":"warn"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-renter-pay-deposit'), 2, 'Problems with paying', '[{"caption":"This car was just taken","say":"Someone confirmed the same car first. The authorization is released and we offer another car or dates.","visual":{"kind":"chat","lines":[{"who":"renter","text":"It says this car was just taken!"},{"who":"you","text":"Someone confirmed it a moment before you. Your card is released. Let me find you another car for the same dates."}]}},{"caption":"Card coverage","say":"With credit card coverage the pay page says Pay with the card that covers this rental and names its network. Another network is stopped.","visual":{"kind":"rule","heading":"The covering card","text":"Pay with the card that covers it, or change the coverage.","tone":"warn"}},{"caption":"Deposit still owed","say":"Picked up before the hold was placed? The booking says Deposit still owed with the amount. The saved card is tried each morning; if not, they get a secure link.","visual":{"kind":"chat","lines":[{"who":"renter","text":"I got a text about my deposit."},{"who":"you","text":"Your deposit hold was not placed at pickup. Tap the link in the text to place it: it is a hold, not a charge, released after the rental."}]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-pay-deposit'), 1, 'When is the deposit taken?', '["When they send the request","About an hour before pickup","After the return","Never"]'::jsonb, 1, 'The deposit is taken at pickup, about an hour before.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-pay-deposit'), 2, 'A renter pays with a debit card. What may happen to the deposit?', '["Nothing differs","It may be charged, with a non-refundable card processing fee","It is waived","It doubles"]'::jsonb, 1, 'Charged instead of held, with the fee shown first.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-pay-deposit'), 3, 'The renter sees This car was just taken. What happened to their card?', '["It was charged","The authorization is released","It was frozen","Nothing"]'::jsonb, 1, 'The authorization is released and we offer another car or dates.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-pay-deposit'), 4, 'With credit card coverage, which card must the renter pay with?', '["Any card","The card that covers this rental","A debit card","Cash"]'::jsonb, 1, 'The covering card: another network is stopped.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-pay-deposit'), 5, 'The booking says Deposit still owed. What do you tell the renter?', '["It is a charge for damage","Tap the secure link to place the hold, released after the rental","Ignore it","Cancel the booking"]'::jsonb, 1, 'It is a hold, not a charge: tap the link or call us.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_path_sections (path_code, section_id, sort) select 'renter_side', (select id from academy_sections where slug = 'r48-renter-pay-deposit'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'renter_side' on conflict (path_code, section_id) do nothing;
insert into academy_sections (slug, title, blurb, guide_refs) values ('r48-renter-coverage', 'Coverage proof: the pink slip and OPCF 27', 'The three options, the two pages for OPCF 27 with the example pictures, and what to tell a renter whose card does not cover the car.', array['renter/before-pickup', 'renter/find-a-car-and-send-a-request']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-renter-coverage'), 1, 'The three options', '[{"caption":"Licence and coverage","say":"On the booking the renter presses Upload documents (or Licence and coverage): the licence front and back, a selfie with it, and the coverage proof.","visual":{"kind":"shot","heading":"Licence and coverage","guide":"renter/before-pickup","img":"renter-09-verify-desktop-d20f668d.jpg"}},{"caption":"What each option needs","say":"Option 1 needs the insurer, the policy number and expiry, and two pages. Option 2 needs the card that covers the car. Option 3, the Protection Plan, needs nothing to upload.","visual":{"kind":"list","heading":"What we need","items":["OPCF 27: the pink slip and the endorsement page","Credit card: pick the card, pay with it","Protection Plan: we confirm it"]}},{"caption":"Before they pay","say":"On OPCF 27 the payment opens once both pages are in, so staff see them before the booking is confirmed.","visual":{"kind":"rule","heading":"Both pages first","text":"No payment until both are uploaded.","tone":"warn"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-renter-coverage'), 2, 'The two pages', '[{"caption":"The pink slip","say":"The pink slip is the liability insurance card for their own car. Next to the upload is an example picture with the parts circled: their name, the policy number, the dates and the insurer.","visual":{"kind":"chat","lines":[{"who":"renter","text":"What is a pink slip?"},{"who":"you","text":"It is the insurance card for your own car, often in your insurer''s app, your email or the glovebox. The example next to the upload shows the parts we need to see."}]}},{"caption":"The endorsement page","say":"The OPCF 27 endorsement page is a page of their policy with the OPCF 27 line. The example circles that line too.","visual":{"kind":"chat","lines":[{"who":"renter","text":"I sent my pink slip, it still says something is needed."},{"who":"you","text":"We have your pink slip. We still need the OPCF 27 endorsement page of your policy: the line on your booking opens that upload."}]}},{"caption":"A good photo","say":"Flat, all four corners, no glare. A PDF works too.","visual":{"kind":"steps","heading":"The photo","items":["Put it flat","All four corners in the photo","No glare"]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-renter-coverage'), 3, 'When the card does not cover it', '[{"caption":"The page says why","say":"No rental damage cover, the car is over the card''s value limit, the kind of car is left out, or the rental is too long. They choose OPCF 27 or the Protection Plan just below.","visual":{"kind":"rule","heading":"Card does not cover","text":"Use OPCF 27 on my policy instead, or Ask for the Protection Plan.","tone":"warn"}},{"caption":"Never say covered","say":"Only the card issuer decides a claim. Send them to the card coverage page and their issuer.","visual":{"kind":"chat","lines":[{"who":"you","text":"Your card issuer decides that. Please call the number on the back of your card about this car and these dates. If it is not covered, OPCF 27 or our Protection Plan work."}]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-coverage'), 1, 'Which two pages does a renter on OPCF 27 upload?', '["Licence front and back","The pink slip and the OPCF 27 endorsement page","A bill and a selfie","The ownership and a receipt"]'::jsonb, 1, 'The pink slip and the endorsement page.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-coverage'), 2, 'What is the pink slip?', '["The rental agreement","The liability insurance card for their own car","A parking ticket","The deposit receipt"]'::jsonb, 1, 'The insurance card for their own car.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-coverage'), 3, 'What do the example pictures next to the upload show?', '["Nothing","The parts that must show, circled: name, policy number, dates, insurer, the OPCF 27 line","The car''s damage","The price"]'::jsonb, 1, 'The parts that must show are circled.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-coverage'), 4, 'When can a renter on OPCF 27 pay?', '["At once","Once both pages are uploaded","After pickup","Never"]'::jsonb, 1, 'The payment opens once both pages are in.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-coverage'), 5, 'Which option needs nothing uploaded for coverage?', '["OPCF 27","Credit card coverage","The CarmaCars Protection Plan","All of them"]'::jsonb, 2, 'The Protection Plan is confirmed by us; no proof to upload.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-coverage'), 6, 'The card coverage check says the car is over the card''s limit. What can the renter choose?', '["Nothing","OPCF 27 on their policy, or the Protection Plan","A cheaper card","Skip coverage"]'::jsonb, 1, 'Use OPCF 27 on my policy instead, or Ask for the Protection Plan.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
