insert into academy_sections (slug, title, blurb, guide_refs) values ('r48-renter-pickup', 'Before pickup and the check-in', 'Do this next and the To do list, the walkthrough, what to bring and checking in themselves.', array['renter/before-pickup']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-renter-pickup'), 1, 'The booking page', '[{"caption":"Do this next","say":"Every booking opens with the car, the status and a clock. Do this next names the one thing still needed, with its red button.","visual":{"kind":"shot","heading":"The booking","guide":"renter/before-pickup","img":"renter-08-booking-confirmed-desktop-b5603da5.jpg"}},{"caption":"The To do list","say":"One line for each thing the booking needs, with its state: Needed, Not accepted (the reason is on the line), Under review, or Done.","visual":{"kind":"list","heading":"States","items":["Needed: send it","Not accepted: read why, send it again","Under review: we are checking","Done"]}},{"caption":"What you say","say":"Ask the renter what Do this next says: it is always the first thing to do.","visual":{"kind":"chat","lines":[{"who":"renter","text":"What else do I need to do before Saturday?"},{"who":"you","text":"Open your booking: Do this next at the top says the one thing left, with its red button. Right now it is your selfie with the licence."}]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-renter-pickup'), 2, 'At pickup', '[{"caption":"What to bring","say":"The original licence (a photo is not enough), the card they paid with, and a few minutes for the walk-around.","visual":{"kind":"list","heading":"Bring","items":["The original licence","The card you paid with","A few minutes for the walk-around"]}},{"caption":"Check in yourself","say":"From 24 hours before pickup the renter can Check in yourself: photos of the car, the odometer and the fuel. Ready bookings are checked in at once; otherwise a team member confirms.","visual":{"kind":"rule","heading":"Check in yourself","text":"From 24 hours before pickup.","tone":"ok"}},{"caption":"The walkthrough","say":"Your rental, step by step: four stages, Before pickup, At pickup, On the road and The return. Field staff see how many steps the renter read.","visual":{"kind":"steps","heading":"The walkthrough","items":["Before pickup","At pickup","On the road","The return"]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-pickup'), 1, 'What does Do this next on the booking show?', '["The price history","The one thing still needed, with its red button","The owner","Nothing"]'::jsonb, 1, 'Always the first thing to do.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-pickup'), 2, 'A line on the To do says Not accepted. What should the renter do?', '["Nothing","Read the reason on the line and send it again","Cancel","Call the bank"]'::jsonb, 1, 'The reason is on the line: send it again.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-pickup'), 3, 'What must the renter bring to pickup?', '["A photo of the licence","The original licence and the card they paid with","Only the booking number","Cash"]'::jsonb, 1, 'A photo is not enough.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-pickup'), 4, 'From when can a renter check in themselves?', '["24 hours before pickup","A week before","After pickup","Never"]'::jsonb, 0, 'From 24 hours before pickup.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-pickup'), 5, 'How many stages does the rental walkthrough have?', '["Two","Four","Six","Ten"]'::jsonb, 1, 'Before pickup, At pickup, On the road, The return.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_path_sections (path_code, section_id, sort) select 'renter_side', (select id from academy_sections where slug = 'r48-renter-pickup'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'renter_side' on conflict (path_code, section_id) do nothing;
insert into academy_sections (slug, title, blurb, guide_refs) values ('r48-renter-trip-extend', 'During the trip: extend, change, report', 'Extend, Ask to change dates, a change we suggest, a problem with the car and an accident.', array['renter/during-your-trip']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-renter-trip-extend'), 1, 'Extend', '[{"caption":"The Extend button","say":"On the booking: Extend, then 1 hour, 3 hours, 1 day, 3 days, 1 week or 1 month. Each shows the new return and the price with HST. An option the car cannot take is greyed out with the reason.","visual":{"kind":"shot","heading":"Extend","guide":"renter/during-your-trip","img":"renter-11-extend-desktop-957274cc.jpg"}},{"caption":"Pay and it is done","say":"Pay with the card on file: when the car is free it is approved at once. Already late? They can still extend, counted from the original return time.","visual":{"kind":"chat","lines":[{"who":"renter","text":"Can I keep the car one more day?"},{"who":"you","text":"Yes: on your booking press Extend, then 1 day. It shows the price, and once you pay it is approved if the car is free."}]}},{"caption":"Never more than late","say":"A few hours cost the hourly late fee, never more than a day, so extending never costs more than being late.","visual":{"kind":"rule","heading":"Extending is cheaper","text":"It keeps the trip covered too.","tone":"ok"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-renter-trip-extend'), 2, 'Changes and problems', '[{"caption":"Ask to change dates","say":"Ask to change dates shows the difference first; nothing changes until they agree to our answer.","visual":{"kind":"shot","heading":"Change dates","guide":"renter/during-your-trip","img":"renter-12-change-desktop-09f6b563.jpg"}},{"caption":"A change we suggest","say":"We suggest a change: the renter presses Review and answer and has 48 hours to accept and sign the amendment, or decline.","visual":{"kind":"rule","heading":"48 hours","text":"One reminder is sent.","tone":"ok"}},{"caption":"Something wrong","say":"Report a problem calls roadside help or opens a message to us. After an accident: Report an accident on the Accident card; anyone hurt, call 911 first.","visual":{"kind":"chat","lines":[{"who":"renter","text":"A warning light came on."},{"who":"you","text":"Please pull over safely. On your booking press Report a problem: it calls roadside help. I am here too."}]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-trip-extend'), 1, 'Which lengths can a renter pick on Extend?', '["Only 1 day","1 hour, 3 hours, 1 day, 3 days, 1 week or 1 month","Only whole weeks","None"]'::jsonb, 1, 'Six choices, each with the new return and price.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-trip-extend'), 2, 'The renter is already past the return time. Can they extend?', '["No","Yes, counted from the original return time","Only by email","Only with an Admin"]'::jsonb, 1, 'They can still extend while they have the car.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-trip-extend'), 3, 'Why is extending never more than being late?', '["It is free","A few hours cost the hourly late fee, never more than a day","Late returns are free","It is not true"]'::jsonb, 1, 'Extending never costs more than being late.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-trip-extend'), 4, 'How long does a renter have to answer a change we suggest?', '["1 hour","48 hours","7 days","No limit"]'::jsonb, 1, '48 hours, with one reminder.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-trip-extend'), 5, 'A renter had an accident and someone is hurt. What first?', '["Report an accident on the booking","Call 911","Text us","Take photos"]'::jsonb, 1, 'Anyone hurt: call 911 first.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_path_sections (path_code, section_id, sort) select 'renter_side', (select id from academy_sections where slug = 'r48-renter-trip-extend'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'renter_side' on conflict (path_code, section_id) do nothing;
insert into academy_sections (slug, title, blurb, guide_refs) values ('r48-renter-return-deposit', 'The return and the deposit back', 'Return the car yourself, I''ve returned the car, km and fuel, the photo report and when the deposit comes back.', array['renter/during-your-trip', 'renter/after-your-trip']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-renter-return-deposit'), 1, 'The return', '[{"caption":"Return it themselves","say":"Return the car yourself: photos of the car where they left it, the odometer, the fuel and the time. With all of them the trip completes at once.","visual":{"kind":"steps","heading":"Return yourself","items":["Photos of the car","The odometer","The fuel","The time"]}},{"caption":"Late notices after returning","say":"Still getting late notices after bringing it back? I''ve returned the car in the notice or on the booking pauses them while we check.","visual":{"kind":"chat","lines":[{"who":"renter","text":"I already returned it but I keep getting late texts."},{"who":"you","text":"Tap I''ve returned the car in the text or on your booking and add a photo if you can. The texts stop while we check."}]}},{"caption":"Km and fuel","say":"Your return: km and fuel shows the km driven, the km included and any over, and the fuel against pickup, with the charge for each.","visual":{"kind":"rule","heading":"Charged from the readings","text":"Km over and fuel short, from the photo report.","tone":"ok"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-renter-return-deposit'), 2, 'The deposit back', '[{"caption":"When it comes back","say":"We release the deposit balance after the return. A toll, ticket or claim still open may keep back what it is expected to cost for a while.","visual":{"kind":"chat","lines":[{"who":"renter","text":"When is my deposit released?"},{"who":"you","text":"After the return, once nothing is open. Tolls and tickets can take up to 7 days to reach us, so the rest can be held until then."}]}},{"caption":"Documents","say":"The photo report, the statement, receipts and agreements are in Documents, with View and Download.","visual":{"kind":"shot","heading":"Documents","guide":"renter/after-your-trip","img":"renter-15-documents-desktop-fd428a63.jpg"}},{"caption":"Late return","say":"A late return is not charged by itself: we look at it, then message them on the booking with what we charged, or that we charged nothing.","visual":{"kind":"rule","heading":"Nothing by itself","text":"A person decides any late charge.","tone":"ok"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-return-deposit'), 1, 'What does Return the car yourself ask for?', '["Nothing","Photos of the car, the odometer, the fuel and the time","A new deposit","A signature on paper"]'::jsonb, 1, 'With all of them the trip completes at once.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-return-deposit'), 2, 'A renter returned the car and still gets late texts. What do you tell them?', '["Ignore them","Tap I''ve returned the car: the texts stop while we check","Pay the late fee","Bring the car back again"]'::jsonb, 1, 'I''ve returned the car pauses the notices.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-return-deposit'), 3, 'Can an open toll keep part of the deposit for a while?', '["No","Yes, what it is expected to cost","Yes, the whole rental price","Only on weekends"]'::jsonb, 1, 'An open toll, ticket or claim may keep back what it is expected to cost.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-return-deposit'), 4, 'Where does the renter find the photo report and the statement?', '["Documents","Rewards","The car page","Nowhere"]'::jsonb, 0, 'Documents has agreements, receipts, statements and uploads.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-return-deposit'), 5, 'Is a late return charged by itself?', '["Yes, at once","No: we look at it, then message them with what we charged","Yes, double","Only the deposit"]'::jsonb, 1, 'A person decides, and the renter is told on the booking.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_path_sections (path_code, section_id, sort) select 'renter_side', (select id from academy_sections where slug = 'r48-renter-return-deposit'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'renter_side' on conflict (path_code, section_id) do nothing;
insert into academy_sections (slug, title, blurb, guide_refs) values ('r48-renter-errors', 'Common errors and what to tell the renter', 'Expired links, sign-in trouble, a card declined, a missing email and the other things renters call about.', array['renter/quick-reference', 'renter/after-your-trip', 'renter/start-here']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-renter-errors'), 1, 'Links and sign-in', '[{"caption":"A link expired","say":"Links in our emails work for 24 hours, once. On that page the renter presses Send me a new link.","visual":{"kind":"chat","lines":[{"who":"renter","text":"The link in your email says it expired."},{"who":"you","text":"Links work once, for 24 hours. On that same page press Send me a new link and use the newest email."}]}},{"caption":"Wrong password","say":"That email and password do not match an account: check the address, or Set a new password. Or sign in with a code by text.","visual":{"kind":"chat","lines":[{"who":"renter","text":"It says my email and password do not match."},{"who":"you","text":"Check the email address first. If it is right, press Set a new password, or press Use my phone number instead and we text you a code."}]}},{"caption":"No confirmation email","say":"Check spam, then Send the confirmation link again on the sign-in form.","visual":{"kind":"list","heading":"No email","items":["Check spam","Send the confirmation link again","Use the newest email only"]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'r48-renter-errors'), 2, 'Other errors', '[{"caption":"Error 1102","say":"Error 1102 on a page is a short limit on our host. Reload the page; they are still signed in.","visual":{"kind":"rule","heading":"Error 1102","text":"Reload the page.","tone":"ok"}},{"caption":"A card declined","say":"An extension or a change with the card declined opens the secure payment page: they enter another card there. Never take a card number by phone or text.","visual":{"kind":"chat","lines":[{"who":"renter","text":"My card was declined for the extension."},{"who":"you","text":"The secure payment page opened: enter another card there. Please never send card numbers by text."}]}},{"caption":"Where to find it","say":"The renter''s Quick reference lists the top tasks and these errors. Send them the page.","visual":{"kind":"shot","heading":"Quick reference","guide":"renter/quick-reference"}},{"caption":"Texts or email","say":"Renters choose Email, Text or Both in Profile. No texts from 9 pm to 8 am, except urgent ones. Reply STOP stops texts; START turns them back on.","visual":{"kind":"list","heading":"Messages","items":["Email, Text or Both in Profile","No texts 9 pm to 8 am, except urgent","STOP and START"]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-errors'), 1, 'How long do links in our emails work?', '["24 hours, once","1 hour","30 days","Forever"]'::jsonb, 0, 'Links work for 24 hours, once: Send me a new link.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-errors'), 2, 'A renter sees Error 1102. What do you tell them?', '["Their account is closed","Reload the page: they are still signed in","Create a new account","Call the bank"]'::jsonb, 1, 'A short limit on our host: reload.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-errors'), 3, 'A renter cannot remember their password. What can they do?', '["Nothing","Set a new password, or sign in with a code by text","Email their password to us","Make a second account"]'::jsonb, 1, 'Set a new password, or Use my phone number instead.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-errors'), 4, 'A card is declined on an extension. What happens?', '["The extension is lost","The secure payment page opens for another card","We charge the deposit","Nothing"]'::jsonb, 1, 'They enter another card on the secure payment page.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-errors'), 5, 'A renter replied STOP. How do they get texts again?', '["They cannot","Text START","Call us","Make a new account"]'::jsonb, 1, 'START turns texts back on.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'r48-renter-errors'), 6, 'Can a renter send you their card number by text?', '["Yes","No: never take a card number by phone or text","Only the last 4 digits and the CVV","Only for deposits"]'::jsonb, 1, 'Cards go only in the secure forms.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_path_sections (path_code, section_id, sort) select 'renter_side', (select id from academy_sections where slug = 'r48-renter-errors'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'renter_side' on conflict (path_code, section_id) do nothing;
insert into academy_enrollments (user_id, path_code, gate, lock_from, source, enrolled_by)
