set local check_function_bodies = off;

create function pg_temp.patch_fn(p_sig regprocedure, p_old text, p_new text) returns void
language plpgsql as $$
declare d text := pg_get_functiondef(p_sig);
begin
  if position(p_old in d) = 0 then raise exception '2990: the text to change was not found in %: %', p_sig, left(p_old, 160); end if;
  execute replace(d, p_old, p_new);
end $$;
create function pg_temp.copy_grants(p_new regprocedure, p_old regprocedure) returns void
language plpgsql as $$
declare g text;
begin
  execute format('revoke all on function %s from public, anon, authenticated', p_new);
  foreach g in array array['anon', 'authenticated', 'service_role'] loop
    if has_function_privilege(g, p_old, 'execute') then execute format('grant execute on function %s to %I', p_new, g); end if;
  end loop;
end $$;

-- 4. the screenshot scene
select pg_temp.patch_fn('app.academy_check_scenes(jsonb)'::regprocedure,
  $o$not in ('title', 'chat', 'list', 'steps', 'money', 'rule') then raise exception 'Each scene needs a picture: title, chat, list, steps, money or rule'$o$,
  $n$not in ('title', 'chat', 'list', 'steps', 'money', 'rule', 'shot') then raise exception 'Each scene needs a picture: title, chat, list, steps, money, rule or shot (a guide screenshot)'$n$);
comment on column academy_lessons.scenes is 'Scenes in order: caption (on screen), say (the narration; the caption when empty) and visual (kind: title, chat, list, steps, money, rule, or shot: a guide screenshot with guide (portal/slug), img and text; 2990).';

-- 2. the shared path
do $$
declare c text;
begin
  for c in select conname from pg_constraint where conrelid = 'public.academy_paths'::regclass and contype = 'c' and pg_get_constraintdef(oid) like '%code%' loop
    execute format('alter table academy_paths drop constraint %I', c);
  end loop;
end $$;
alter table academy_paths add constraint academy_paths_code_check
  check (code in ('cs', 'fleet', 'finance', 'sales_in_person', 'sales_remote', 'field', 'admin', 'renter_side'));
values ('renter_side', 'The renter''s side', 'What the renter sees, step by step: the request, the offer, signing, paying and the deposit, coverage proof, pickup, the trip, the return, and the errors renters call about.', 8)
on conflict (code) do update set title = excluded.title, blurb = excluded.blurb, sort = excluded.sort;
comment on table academy_paths is 'The academy''s paths (0207), one per staff function (Sales in person and remote apart, and Admin), and The renter''s side (2990) for every staff member.';

alter function app.academy_paths_of(uuid) rename to academy_paths_of_pre2990;
create function app.academy_paths_of(p_user uuid) returns text[]
language sql stable security definer set search_path = public, app as $$
  select case when cardinality(x) = 0 then x else (select array_agg(distinct p order by p) from unnest(x || array['renter_side']) p) end
    from (select app.academy_paths_of_pre2990(p_user) as x) s
$$;
select pg_temp.copy_grants('app.academy_paths_of(uuid)'::regprocedure, 'app.academy_paths_of_pre2990(uuid)'::regprocedure);
comment on function app.academy_paths_of(uuid) is 'The academy paths of a person (0207, 0931): those of their functions, and The renter''s side (2990) for anyone with a path.';

-- 3. who had passed everything before the new sections (for their 7 days)
create temp table r48_done on commit drop as
select distinct e.user_id from academy_enrollments e where app.academy_done(e.user_id);

