-- 3. the renter's side on the enrollments that hold (hire or admin), and 7 days for those who had passed everything
select distinct e.user_id, 'renter_side', true, case when d.user_id is null then now() else now() + interval '7 days' end, 'admin', null::uuid
  from academy_enrollments e left join r48_done d on d.user_id = e.user_id
 where e.gate and e.source in ('hire', 'admin') and not app.user_is_admin(e.user_id)
on conflict (user_id, path_code) do nothing;
update academy_enrollments e set lock_from = greatest(e.lock_from, now() + interval '7 days')
  from r48_done d where e.user_id = d.user_id and e.gate;
